package com.example.playlist;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.*;import android.net.Uri;import android.provider.MediaStore;import android.content.ContentValues;import java.io.*;import android.util.Base64;
public class MainActivity extends Activity{
 WebView web;ValueCallback<Uri[]> cb;static final int REQ=42;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff0b1020);web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setMediaPlaybackRequiresUserGesture(false);web.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){if(cb!=null)cb.onReceiveValue(null);cb=c;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("audio/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,REQ);return true;}});web.addJavascriptInterface(new Bridge(this),"AndroidDownload");web.loadUrl("file:///android_asset/index.html");setContentView(web);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r!=REQ)return;Uri[] a=null;if(c==RESULT_OK&&d!=null){if(d.getClipData()!=null){a=new Uri[d.getClipData().getItemCount()];for(int i=0;i<a.length;i++)a[i]=d.getClipData().getItemAt(i).getUri();}else if(d.getData()!=null)a=new Uri[]{d.getData()};}if(cb!=null){cb.onReceiveValue(a);cb=null;}}
 public static class Bridge{final Context c;Bridge(Context x){c=x;}@JavascriptInterface public void saveBase64(String name,String mime,String data){new Thread(()->{try{byte[] b=Base64.decode(data,Base64.DEFAULT);if(Build.VERSION.SDK_INT>=29){ContentValues v=new ContentValues();v.put(MediaStore.Downloads.DISPLAY_NAME,name);v.put(MediaStore.Downloads.MIME_TYPE,mime);v.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/Playlist Studio");v.put(MediaStore.Downloads.IS_PENDING,1);Uri u=c.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);try(OutputStream o=c.getContentResolver().openOutputStream(u)){o.write(b);}v.clear();v.put(MediaStore.Downloads.IS_PENDING,0);c.getContentResolver().update(u,v,null,null);}else{File f=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),name);try(FileOutputStream o=new FileOutputStream(f)){o.write(b);}}}catch(Exception e){}}).start();}}
}